import itertools

# T descriptors: (stem_y, stem_x, bar_y, bar_xc, dir)
d1T = [((1,3,2,2,'u')), ((9,2,10,2,'u')), ((9,13,10,13,'u')),
       ((5,8,4,8,'d')), ((6,1,5,1,'d')), ((9,6,8,6,'d')), ((13,7,12,7,'d'))]
d2T = [((3,1,4,1,'u')), ((1,1,0,1,'d'))]
d2cells = {(3,1,'u'):(0,0),(1,1,'d'):(0,3)}  # known

uT = [t for t in d1T if t[4]=='u']; dT = [t for t in d1T if t[4]=='d']

def anchors(t,H,W):
    sy,sx,by,bx,d = t
    return {
      'stem':(sy,sx), 'bar':(by,bx), 'bboxc':((sy+by)/2,(sx+bx)/2),
      'bbox_tl':(min(sy,by),min(sx,bx)-1), 'bbox_br':(max(sy,by),max(sx,bx)+1),
      'stemy_barx':(sy,bx), 'bary_stemx':(by,sx),
    }

def transforms(y,x,H,W):
    return {'id':(y,x),'flipY':(H-1-y,x),'flipX':(y,W-1-x),'rot180':(H-1-y,W-1-x)}

def block(v,n,H):  # map coord v (in H) to block index 0..n-1 with offset
    return [min(n-1, int((v+o)*n//H)) for o in range(3)]

results=[]
for pu in itertools.permutations([(0,0),(0,2),(2,0)]):
    for pd in itertools.permutations([(0,0),(0,2),(2,0),(2,2)]):
        asg={}
        for t,cell in zip(uT,pu): asg[t]=(cell[0],cell[1])
        for t,cell in zip(dT,pd): asg[t]=(cell[0],2+cell[1])
        for t,cell in d2cells.items():
            for tt in d2T:
                if (tt[0],tt[1],tt[4])==t: asg[tt]=(cell[0],cell[1])
        # for each anchor/transform/offset: check mapping consistency
        for an in ['stem','bar','bboxc','bbox_tl','bbox_br','stemy_barx','bary_stemx']:
            for tf in ['id','flipY','flipX','rot180']:
                for offR in range(3):
                    for offC in range(3):
                        ok=True
                        mapping=[]
                        for t,H,W in [(t,15,15) for t in d1T]+[(t,5,4) for t in d2T]:
                            y,x = anchors(t,H,W)[an]
                            yy,xx = transforms(y,x,H,W)[tf]
                            rs = block(yy,3,H); cs = block(xx,6,W)
                            r = rs[offR]; c = cs[offC]
                            c = c if asg[t][1]<3 else (c if c%2==0 else c-1)  # keep parity: map col in {0,2}->out col {0,2} or {3,5}
                            m = 1 if (c in (2,5)) else 0
                            if (r,c) != asg[t]: ok=False; break
                            mapping.append((t,(r,c)))
                        if ok: results.append((an,tf,offR,offC))
uniq=set(results)
